import { II, CS, type Item, type Options } from "./build";
import type { Difficulty } from "../types";
const items: Item[] = [];
type Q = [skill: string, difficulty: Difficulty, stem: string, options: Options];
function r(id: string, source: string, locator: string, passage: string, questions: Q[]) {
  questions.forEach(([skill, difficulty, stem, options], i) => items.push({ id: `${id}-${i + 1}`, source, locator, passage, skill, difficulty, stem, options, family: id, domain: skill === "Text Structure and Purpose" ? CS : II }));
}

r("wick", "faraday", "Lecture I: capillary attraction and the candle wick",
"In Faraday's account, the candle wick is not simply a thread that happens to burn. Melted fuel rises through its fine spaces by capillary action, much as water enters a towel. The flame supplies the heat that melts the solid fuel, while the wick delivers the resulting liquid to the region where it can vaporize. Thus, the continued operation of an ordinary candle depends on several processes sustaining one another, rather than on the combustion of an isolated piece of string.", [
["Central Ideas and Details",2,"Which choice best states the central idea?",[
["A candle's sustained burning depends on interacting processes that move and transform its fuel.","Плавление, подъём жидкости и испарение поддерживают горение совместно."],
["A candle's wick supplies most of the energy released as its surrounding fuel melts.","Текст не называет нить главным источником энергии."],
["Capillary action becomes effective only after a candle's liquid fuel has vaporized.","Капиллярный подъём относится к жидкости до испарения."],
["The resemblance between a wick and a towel establishes that both materials burn similarly.","Аналогия объясняет впитывание, а не сходство горения."]]],
["Inferences",3,"Which inference is best supported?",[
["A wick unable to transport liquid could interrupt burning even if solid fuel remained nearby.","Наличие запаса не заменяет доставку топлива в область испарения."],
["Any thread placed near solid fuel will necessarily maintain a stable flame.","Не любая нить обеспечивает описанные процессы."],
["Fuel movement through the wick is caused exclusively by the upward movement of hot air.","В тексте указан другой механизм — капиллярное действие."],
["The candle can continue burning indefinitely without further changes in its fuel.","Работа требует постоянного превращения топлива."]]],
["Text Structure and Purpose",2,"What is the main purpose of the reference to a towel?",[
["To connect an unfamiliar fuel-transport mechanism with a familiar example of liquid absorption.","Знакомое впитывание помогает понять капиллярный подъём."],
["To identify a household material that would be a more efficient substitute for candle fuel.","Никакого сравнения эффективности топлива нет."],
["To show that the flame itself physically pushes liquid upward through the wick.","Тепло плавит топливо; аналогия не доказывает давление пламени."],
["To distinguish an effect that depends on burning from one that can occur only in water.","Капиллярное действие описано и для воды, и для топлива."]]],
]);
r("hollow-flame","faraday","Lecture I: drawing vapor from the interior of a flame",
"A bright candle flame can appear to be a uniformly burning mass. Faraday inserts a narrow tube into its dark interior and conducts material from that region to a point outside the flame, where it can be ignited. The demonstration reveals combustible vapor in a place that, viewed from outside, might be mistaken for the brightest region's continuation. A flame's visible outline therefore conceals internal differences that a simple observation of its silhouette would not disclose.",[
["Central Ideas and Details",2,"What does the demonstration primarily establish?",[["Different regions inside a candle flame need not be undergoing the same process.","Из тёмной области извлекается ещё горючий пар."],["The darkest part of a flame contains no material capable of burning.","Извлечённое вещество как раз зажигается."],["A candle becomes brighter whenever a narrow tube is brought near its surface.","Яркость не является проверяемым результатом."],["A flame's visible outline directly shows where all of its fuel has been consumed.","Внешний контур скрывает внутреннее различие."]]],
["Inferences",3,"Which observation would most directly undermine the stated interpretation of the experiment?",[["The tube generates the ignitable vapor itself rather than transporting it from the flame.","Тогда результат нельзя приписать содержимому внутренней области."],["The transported vapor burns only after reaching the tube's outer opening.","Именно это и описано; это не опровержение."],["The candle's outline remains recognizable while the tube is in place.","Сохранение контура не отменяет различия областей."],["Some observers fail to notice the dark interior before the experiment.","Это согласуется с ограниченностью внешнего наблюдения."]]],
["Text Structure and Purpose",3,"How does the first sentence function in the text?",[["It introduces an impression that the subsequent intervention gives reason to qualify.","Видимость однородности проверяется и уточняется опытом."],["It states an experimental result that the remaining sentences accept without qualification.","Это исходное впечатление, а не результат опыта."],["It identifies a historical explanation that the author defends against Faraday's findings.","Автор использует опыт для уточнения впечатления."],["It provides a definition of combustion that determines how the experiment must end.","Определения горения в первом предложении нет."]]],
]);
r("soot","faraday","Lecture II: luminous carbon and soot deposited on a plate",
"Faraday holds a cold plate in the luminous part of a candle flame, and soot collects on the plate. He connects the deposit with particles of carbon that become incandescent in the flame. Brightness, on this account, does not by itself demonstrate that a fuel has been consumed completely. Indeed, interrupting the process can preserve material that was contributing to the light. The black deposit and the brilliant appearance are therefore evidence concerning different stages of the same material's behavior.",[
["Central Ideas and Details",2,"Which choice best summarizes the relationship described?",[["Carbon can contribute to a flame's light before being deposited as soot when the process is interrupted.","Один материал связывает свечение и осадок на пластинке."],["The blackness of soot shows that carbon could not previously have contributed to the light.","Текст прямо связывает углерод с яркостью."],["A cold plate makes the fuel vanish more completely than an uninterrupted flame would.","На пластинке остаётся вещество, а не исчезает."],["A brighter flame necessarily leaves less unconsumed material than a dimmer flame.","Яркость сама по себе этого не гарантирует."]]],
["Inferences",3,"Which conclusion is most strongly supported?",[["An apparently efficient visual effect can coexist with material that has not yet completed combustion.","Сильный свет не равен завершению всех превращений."],["Deposits obtained from a flame must consist of material produced by the plate itself.","Происхождение осадка связывается с пламенем."],["All luminous objects release particles of carbon when cooled.","Вывод обо всех светящихся объектах выходит за пределы текста."],["Soot can form only in flames too faint to be seen without special equipment.","Опыт проводится в яркой части видимого пламени."]]],
["Text Structure and Purpose",2,"Why does the text contrast the black deposit with the brilliant appearance?",[["To reconcile observations that may seem inconsistent by linking them to different stages.","Контраст объясняется разными состояниями одного материала."],["To reject the observation that soot actually collected on the plate.","Сбор осадка принимается как факт опыта."],["To suggest that color alone identifies the exact chemical composition of any flame.","Такая общая методика не предлагается."],["To compare the accuracy of two witnesses who disagree about one event.","Два наблюдения не принадлежат спорящим свидетелям."]]],
]);
r("water-product","faraday","Lecture II: water as a product of candle combustion",
"Faraday collects a liquid produced while a candle burns and identifies it as water. A candle may feel dry before it is lit, so a spectator might suppose that the liquid had simply been stored inside it. Faraday instead treats the water as a product of combustion. The experiment invites a distinction between substances initially present in a familiar object and substances that can be formed when that object undergoes chemical change.",[
["Central Ideas and Details",2,"What distinction does the text emphasize?",[["A substance produced by a reaction need not have been present in that form before the reaction.","Продукт может образоваться при химическом изменении."],["A liquid can be identified reliably only when its source was already visibly wet.","Полученная вода идентифицируется вопреки сухости свечи."],["Every familiar object contains hidden water that heat merely releases unchanged.","Это отвергаемое предположение, а не вывод."],["The physical appearance of a candle directly determines the composition of every product.","Внешний вид как раз не даёт такого вывода."]]],
["Command of Evidence (Textual)",3,"Which additional finding would most directly challenge the spectator's proposed explanation?",[["A dry fuel containing no stored liquid water also yields water when it burns under controlled conditions.","Получение воды без исходной жидкой воды ослабляет объяснение хранением."],["The collected water resembles water obtained from a nearby tap.","Сходство воды не устанавливает, хранилась ли она заранее."],["The candle is shorter after burning than it was before the experiment.","Изменение длины не различает два объяснения появления воды."],["A wet candle is more difficult to light than an otherwise similar dry candle.","Зажигание мокрой свечи не проверяет происхождение продукта."]]],
["Text Structure and Purpose",2,"What is the role of the spectator's supposition?",[["It supplies an intuitive alternative that clarifies the significance of Faraday's interpretation.","Альтернатива делает видимым различие высвобождения и образования."],["It reports the final explanation that Faraday accepts after abandoning combustion.","Фарадей трактует воду как продукт горения."],["It establishes that spectators had already measured the candle's internal composition.","Предположение не является измерением состава."],["It proves that a dry surface cannot conceal any kind of liquid.","Такого доказательства нет; речь о происхождении воды."]]],
]);
r("air-supply","faraday","Lecture II: air necessary for combustion",
"A candle burning beneath a closed vessel eventually goes out. This result alone might tempt an observer to say that any enclosed space prevents burning. Yet the relevant feature is not enclosure considered in isolation: the flame changes the available air, and the supply is not renewed. Faraday's demonstrations direct attention to the material conditions of combustion. The shape of the vessel is less informative than whether the surroundings can continue to provide what the reaction requires.",[
["Central Ideas and Details",2,"Which claim best states the main idea?",[["The effect of enclosure should be explained through the changing supply of materials needed for combustion.","Замкнутость действует через условия снабжения реакции."],["The vessel's shape is sufficient to predict exactly how long any candle will burn.","Форма названа менее информативной, точного прогноза нет."],["A candle extinguishes as soon as any object is placed anywhere above it.","Текст описывает постепенное прекращение в закрытом сосуде."],["Enclosure affects a flame without producing any change in the surrounding air.","Изменение доступного воздуха — центральное звено."]]],
["Command of Evidence (Textual)",3,"Which comparison would most directly test the explanation favored in the text?",[["Compare identical enclosed candles when suitable fresh air is supplied to only one vessel.","Меняется возобновление воздуха при одинаковой замкнутости."],["Compare candles of different sizes burning in vessels of different shapes and volumes.","Одновременно меняются несколько существенных факторов."],["Compare the colors of two unlit candles placed in the same closed vessel.","Без горения не проверяется расход материалов."],["Compare a closed vessel without a candle with an open vessel without a candle.","Такой опыт не измеряет поддержание горения."]]],
["Inferences",3,"Which inference follows most reasonably?",[["An intervention may alter combustion even when the visible boundary around the candle remains unchanged.","Подача воздуха способна менять условия без изменения стенок."],["A candle's extinction establishes that no gas remains anywhere inside its vessel.","Недостаток нужного компонента не равен отсутствию любого газа."],["The vessel's geometry can never affect the amount of air initially available.","Меньшая информативность формы не означает отсутствия влияния объёма."],["Replacing a vessel with an identical one necessarily restores the original air supply.","Тождественность формы не гарантирует состава содержимого."]]],
]);
r("breath","faraday","Lecture VI: respiration and combustion; carbonic acid",
"Faraday compares a candle's combustion with processes occurring in animal respiration. The comparison concerns transformations of materials, including the production of carbon dioxide, rather than a claim that lungs contain a visible flame. By linking an everyday object to a living process, he broadens the reach of the chemical explanation. Its usefulness depends on the specific similarities identified, not on treating candles and animals as identical in every respect.",[
["Central Ideas and Details",2,"What is the main point of the text?",[["A carefully limited comparison can connect combustion and respiration without equating the systems completely.","Аналогия основана на конкретных химических сходствах."],["Respiration can be understood only by assuming that a visible flame burns inside every lung.","Это прямо исключённое понимание аналогии."],["The differences between animals and candles prevent any meaningful chemical comparison.","Текст обосновывает полезность ограниченного сравнения."],["The production of carbon dioxide is the only feature shared by all living and nonliving systems.","Универсального утверждения обо всех системах нет."]]],
["Inferences",3,"Which criticism would miss the intended scope of the comparison?",[["Animals can move voluntarily, whereas a candle cannot, so their chemical processes cannot be compared.","Различие вне выбранного химического аспекта не опровергает аналогию."],["One of the products named in the comparison is not actually formed under the specified conditions.","Это было бы релевантной проверкой конкретного сходства."],["The evidence for a proposed shared material transformation has been measured inaccurately.","Качество химических измерений относится к аргументу."],["An explanation incorrectly identifies which material is consumed during either process.","Такое возражение касается выбранного предмета сравнения."]]],
["Text Structure and Purpose",2,"Why does the author mention the absence of a visible flame in lungs?",[["To prevent a literal extension of an analogy beyond the feature it is meant to illuminate.","Уточнение ограничивает перенос свойств свечи на организм."],["To concede that the chemical products of respiration have never been observed.","Не утверждается отсутствие наблюдений продуктов."],["To show that visible appearance is the only basis for all scientific comparisons.","Сравниваются превращения веществ, а не только вид."],["To replace a chemical explanation with an account of voluntary movement.","Химическая тема сохраняется."]]],
]);
r("double-vision","dubois","Of Our Spiritual Strivings: double-consciousness",
"Du Bois describes a divided form of self-awareness: a person experiences life directly while also being compelled to see that life through the judgments of a society that devalues it. The division does not simply amount to having two unrelated interests. It arises because an external standard presses upon the person's understanding of the self. His account therefore connects an apparently inward psychological difficulty to a social relationship, rather than locating its cause solely within an individual's temperament.",[
["Central Ideas and Details",3,"Which statement best captures the central idea?",[["A socially imposed viewpoint can become part of a person's conflicted experience of selfhood.","Внешняя общественная оценка вмешивается в самовосприятие."],["Having multiple interests necessarily prevents a person from developing a coherent identity.","Текст специально отличает проблему от разных интересов."],["An individual's temperament fully explains how society evaluates that individual's identity.","Причина не сведена к темпераменту; направление связи перевёрнуто."],["Direct experience of life always eliminates the influence of external judgments.","Оба взгляда сосуществуют в описанной сложности."]]],
["Inferences",3,"Which inference is most strongly supported?",[["Changing an individual's private attitude alone may leave an important source of the conflict intact.","Источник включает социальные отношения, а не только внутреннюю установку."],["People subject to devaluation must agree with every judgment made about them.","Вынужденный учёт чужого взгляда не означает согласия."],["Every form of uncertainty about identity results from exactly the same social mechanism.","Рассматривается конкретная форма, не все возможные сомнения."],["Social relationships influence identity only when a person has no direct personal experiences.","Внешний взгляд действует одновременно с личным опытом."]]],
["Text Structure and Purpose",3,"What does the contrast with 'two unrelated interests' accomplish?",[["It rules out a superficial interpretation before specifying the social source of the division.","Контраст уточняет смысл описываемой двойственности."],["It introduces the interpretation that the final sentence presents as a sufficient explanation.","Именно эта поверхностная трактовка отклоняется."],["It establishes that all conflicting interests originate in hostile social judgments.","Все интересы не объявлены продуктом общественной враждебности."],["It shifts the discussion away from identity and toward leisure activities.","Тема самосознания не меняется."]]],
]);
r("veil","dubois","The Forethought and Of Our Spiritual Strivings: the Veil",
"Du Bois's image of a veil represents a barrier in social understanding, not merely a physical separation between people. Those on one side may be seen without being understood on their own terms. In presenting experiences from within the veil, the writer seeks to make a neglected perspective available to readers outside it. The metaphor thus concerns unequal access to interpretation: physical proximity does not ensure that one group's accounts of its own life will receive an adequate hearing.",[
["Central Ideas and Details",2,"Which idea is most central to the passage?",[["Social closeness can coexist with a failure to recognize another group's own perspective.","Видимость и близость не равны пониманию опыта группы."],["Physical distance is the only obstacle preventing readers from learning about other people.","Барьер назван интерпретационным, не только физическим."],["The metaphor suggests that no perspective can ever be communicated across social divisions.","Само письмо пытается сделать перспективу доступной."],["Readers within the veil are necessarily less capable of interpreting any written account.","Неравенство касается признания перспективы, не способностей читателей."]]],
["Inferences",3,"Which outcome would best fulfill the purpose attributed to the writer?",[["Readers reconsider familiar social descriptions after encountering accounts from those previously described only by outsiders.","Внутренний голос меняет привычное внешнее толкование."],["Readers learn the physical location of a community but continue to ignore its members' testimony.","Географическое знание не устраняет барьер интерпретации."],["Readers assume that seeing a group in public gives them complete knowledge of its experience.","Это сохраняет отождествление видимости и понимания."],["Readers replace every individual account with a single description based on appearance.","Такой результат вновь исключает внутреннюю перспективу."]]],
["Text Structure and Purpose",2,"What is the function of the final sentence?",[["It restates the metaphor's interpretive implication in more explicit social terms.","Финал раскрывает, какой именно доступ ограничен."],["It contradicts the claim that the writer hopes to address readers outside the veil.","Разъяснение поддерживает эту цель."],["It gives a chronological account of how the physical barrier was constructed.","Истории строительства нет; барьер метафорический."],["It introduces evidence that the metaphor refers exclusively to clothing.","Исключительно буквальное прочтение отвергается."]]],
]);
r("sorrow-song","dubois","Of the Sorrow Songs: spirituals as historical expression",
"Du Bois treats spirituals as more than melodies detached from the people who created them. Their musical form carries a record of suffering, aspiration, and endurance that conventional written histories may fail to preserve. This does not make every song a literal chronicle of a particular event. Rather, their evidentiary value includes the collective feelings and expectations that they express. Assessing them solely by whether each line identifies a verifiable occurrence would overlook an important kind of historical knowledge.",[
["Central Ideas and Details",3,"Which statement best conveys the text's main idea?",[["Songs can preserve dimensions of historical experience that are not reducible to records of individual events.","Коллективные чувства и надежды тоже составляют историческое свидетельство."],["A song has historical value only if every line can be matched to a documented event.","Такой критерий объявлен недостаточным."],["Musical expression prevents listeners from learning anything about its creators' expectations.","Именно ожидания названы частью сохраняемого опыта."],["Written histories and songs invariably preserve precisely the same aspects of the past.","Песни могут сохранять то, что письменные истории упускают."]]],
["Inferences",3,"Which scholarly approach best aligns with this account?",[["Examine recurring emotional themes in songs alongside documentary records without treating the songs as literal transcripts.","Подход сохраняет выразительное свидетельство и различает типы источников."],["Reject any song whose lyrics do not provide dates for all the experiences they evoke.","Это применяет отвергаемый узкий критерий."],["Use the presence of melody as sufficient proof that all stated events occurred exactly as described.","Музыкальность не доказывает буквальную фактичность."],["Replace all written records with songs because emotional expression eliminates the need for corroboration.","Вытеснение документов и отказ от проверки не обоснованы."]]],
["Text Structure and Purpose",2,"Why does the author state that not every song is a literal chronicle?",[["To qualify the kind of historical evidence being claimed rather than deny the songs' value.","Оговорка уточняет вид свидетельства, сохраняя его значимость."],["To withdraw the initial claim that the songs convey a record of experience.","После оговорки ценность объясняется, а не отзывается."],["To argue that only instrumental music can communicate collective feelings.","Противопоставления вокальной и инструментальной музыки нет."],["To show that historical knowledge is confined to individually verified dates.","Именно такой узкий подход критикуется."]]],
]);
r("education-horizon","dubois","Of the Wings of Atalanta: education beyond money-getting",
"In his discussion of education, Du Bois questions a standard that measures learning entirely by immediate financial return. Occupational preparation has practical importance, but he also values intellectual development and participation in a broader human inheritance. The dispute is therefore not simply between useful work and useless study. It concerns whether one useful function of education should be allowed to define the whole enterprise and to exclude forms of growth whose benefits are less immediately measurable.",[
["Central Ideas and Details",2,"Which choice best states the main claim?",[["Education's economic usefulness should be recognized without making it the sole measure of educational worth.","Практическая функция признаётся, но не исчерпывает ценность."],["Occupational preparation has no practical value for any student.","Её значение прямо признаётся."],["Intellectual development matters only when its financial benefit can be measured immediately.","Это как раз оспариваемый критерий."],["A useful occupation necessarily prevents participation in a wider intellectual tradition.","Несовместимость не утверждается."]]],
["Inferences",3,"Which policy would be least consistent with the reasoning?",[["Eliminate every course whose contribution to next year's earnings cannot be quantified.","Политика превращает немедленный доход в единственный критерий."],["Provide occupational instruction while retaining opportunities for broad intellectual inquiry.","Такой подход учитывает обе признанные функции."],["Evaluate some educational benefits over a longer period than a single hiring cycle.","Это согласуется с отсроченными и менее измеримыми эффектами."],["Ask whether a curriculum cultivates judgment as well as employable skills.","Расширение критериев соответствует аргументу."]]],
["Text Structure and Purpose",3,"How does the text characterize the dispute in its third sentence?",[["By rejecting a misleading opposition so that the actual disagreement about criteria becomes clear.","Противопоставление полезного и бесполезного заменяется спором о полноте критерия."],["By conceding that intellectual growth and practical preparation cannot coexist.","Такое противопоставление прямо отвергается."],["By narrowing the inquiry to differences in wages between two named occupations.","Конкретных профессий и ставок оплаты нет."],["By treating financial return as irrelevant to every educational decision.","Одна функция признана важной, а не нерелевантной."]]],
]);
r("rural-school","dubois","Of the Meaning of Progress: the Tennessee school and return visit",
"Du Bois recalls a rural community in which he once taught and later returned to find visible signs of change. A simple inventory of new buildings or altered routines, however, cannot settle what progress has meant for the people he knew. Personal losses and continuing constraints complicate the surface picture of advancement. The retrospective account asks readers to consider whose experience is included when an observer converts social change into a confident story of collective improvement.",[
["Central Ideas and Details",3,"What is the central idea of the text?",[["Visible social changes may be an incomplete measure of improvement in the lives of particular people.","Материальные перемены не исчерпывают человеческих результатов."],["Every visible alteration in a rural community necessarily worsens its residents' lives.","Все изменения не названы ухудшением."],["An observer can establish collective progress simply by counting newly constructed buildings.","Достаточность такого счёта ставится под сомнение."],["Personal recollections are useful only when no physical changes have occurred.","Воспоминания нужны именно для усложнения картины перемен."]]],
["Inferences",3,"Which additional information would best address the account's concern?",[["Evidence about how opportunities and burdens changed for residents who did not share equally in the visible improvements.","Такое свидетельство включает опыт, который общий рассказ может скрывать."],["A more precise count of buildings, with no information about the people using them.","Уточняется тот же ограниченный показатель."],["A comparison of the narrator's writing style with that of an unrelated urban novelist.","Стиль другого автора не проверяет последствия перемен для жителей."],["An assurance that the word progress has the same spelling in every report.","Совпадение слова не определяет реальное благополучие."]]],
["Text Structure and Purpose",2,"What role does the return visit play?",[["It creates a comparison over time through which an apparently simple narrative of advancement can be questioned.","Возвращение позволяет сопоставить изменения и человеческие судьбы."],["It establishes that the narrator had never previously encountered the community.","Он ранее преподавал там."],["It removes personal experience so that only construction statistics remain relevant.","Личные потери как раз усложняют статистическую картину."],["It proves that the earlier community was unaffected by social constraints.","Такого описания прошлого нет."]]],
]);
r("book-learning","douglass","Chapters VI–VII: literacy, opposition and self-directed learning",
"When Douglass's initial reading instruction is stopped, the opposition itself helps reveal to him why literacy matters. A prohibition intended to limit his possibilities exposes a connection between knowledge and the maintenance of domination. He then pursues learning through other means. In this account, an attempt to deny access to a skill inadvertently supplies an argument for acquiring it: the lesson lies not only in the words he learns but also in the reasons others offer for keeping him from them.",[
["Central Ideas and Details",2,"Which choice best expresses the central idea?",[["Opposition to Douglass's learning unintentionally clarifies the power that learning could give him.","Запрет обнаруживает политическое значение грамотности."],["The termination of formal instruction convinces Douglass that reading has little value.","Его дальнейшие действия показывают обратное."],["Douglass acquires literacy only because everyone around him considers it harmless.","Важную роль играет именно противодействие."],["Learning a skill and understanding the reasons for its restriction are unrelated in this account.","Текст соединяет оба вида понимания."]]],
["Inferences",3,"Which generalization is best supported by the account?",[["An effort to conceal a resource's importance can reveal that importance through the explanation offered for withholding it.","Объяснение ограничения может выдать то, что оно охраняет."],["Every prohibition eventually gives its subject the complete ability that it seeks to restrict.","Осознание значения не тождественно автоматическому овладению."],["The value of literacy derives exclusively from the approval of those already in authority.","Ценность открывается вопреки такому одобрению."],["Self-directed learning requires that a learner never receive help from anyone else.","Иные способы не исключают помощи."]]],
["Text Structure and Purpose",3,"What is the main effect of the final sentence?",[["It distinguishes the acquisition of reading skills from a second kind of understanding gained through resistance to them.","Финал отделяет навык от понимания социальной причины запрета."],["It retracts the claim that Douglass continues to pursue literacy.","Продолжение обучения не отрицается."],["It explains why the words Douglass learns have no practical significance.","Значимость слов не отрицается; добавляется другой урок."],["It introduces a new narrator who endorses the prohibition.","Нового рассказчика нет."]]],
]);
r("songs-misread","douglass","Chapter II: the meaning of the enslaved people's songs",
"Douglass objects to observers who interpret enslaved people's singing as straightforward proof of contentment. The sound that outsiders hear may express grief or provide a response to suffering rather than indicate its absence. His objection turns on the difference between noticing a behavior and correctly interpreting the conditions that give it meaning. A familiar association between singing and happiness, applied without attention to the singers' situation, can reverse rather than illuminate the significance of the evidence.",[
["Central Ideas and Details",2,"Which idea does the text primarily develop?",[["An observer's familiar interpretation of a behavior may be misleading when its social context is ignored.","Обычная ассоциация не заменяет понимания обстоятельств."],["The presence of singing reliably establishes that all participants are content.","Именно этот вывод оспаривается."],["Music can express suffering only when listeners already share the singers' experiences.","Необходимость общего опыта для выражения не заявлена."],["Observing behavior gives outsiders no evidence of any kind about other people's lives.","Критикуется неверное толкование, а не наблюдение вообще."]]],
["Command of Evidence (Textual)",3,"Which finding would most directly support the objection?",[["Singers describe the songs as expressions of loss even during periods outsiders label cheerful on the basis of the singing.","Само описание исполнителей опровергает внешний вывод о довольстве."],["Some outsiders can reproduce the melodies accurately after hearing them once.","Точность воспроизведения не устанавливает значение песни."],["The songs contain repeated musical phrases rather than changing melody in every line.","Музыкальное строение не проверяет довольство исполнителей."],["Observers generally recognize that the sounds they hear are produced by human voices.","Распознавание источника звука не проверяет его социальный смысл."]]],
["Inferences",3,"Which inference follows most reasonably?",[["Evidence that appears to confirm a belief may challenge it once the perspective of those producing the evidence is considered.","Контекст исполнителей способен изменить направление вывода."],["A single behavior must always express the same emotion in every historical setting.","Текст ставит под сомнение такой перенос."],["People who experience suffering necessarily stop engaging in artistic activities.","Существование этих песен показывает обратное."],["Correctly recognizing a melody guarantees a correct account of the singer's circumstances.","Распознавание и интерпретация обстоятельств различаются."]]],
]);
r("education-reason","wollstonecraft","Introduction and Chapter II: reason, dependence and education",
"Wollstonecraft challenges an account of education that trains women to win approval while denying them opportunities to develop independent judgment. If apparent weakness has been cultivated by social training, it cannot simply be cited as proof of an unalterable natural incapacity. Her criticism therefore questions both the educational arrangement and the inference used to justify it. A system may help produce the very behavior that its defenders later present as a reason for preserving the system.",[
["Central Ideas and Details",3,"Which statement best captures the argument?",[["Behavior shaped by restrictive education cannot, without further evidence, establish that the restriction reflects natural incapacity.","Воспитанный результат не доказывает природную неизбежность ограничения."],["Education can improve judgment only if it aims exclusively at winning social approval.","Такое воспитание как раз ограничивает самостоятельность."],["Any difference observed after education proves that education had no effect on the learners.","Влияние обучения не исключено, а подчёркнуто."],["An institution is justified whenever its defenders can describe behavior occurring within it.","Происхождение поведения делает такое обоснование круговым."]]],
["Inferences",3,"Which research design would most directly address the disputed inference?",[["Compare the development of judgment under educational arrangements that differ in the opportunities for independent reasoning.","Различие условий позволяет проверить роль воспитания."],["Observe only people trained under the restrictive arrangement and assume the arrangement had no influence.","Так повторяется оспариваемое допущение."],["Measure how often defenders repeat the claim without examining learners' opportunities.","Частота повторения не проверяет причину поведения."],["Define incapacity as any behavior that fails to win approval from the existing system.","Определение заранее закрепляет круговой критерий."]]],
["Text Structure and Purpose",3,"What does the final sentence contribute?",[["It states the circular pattern underlying the justification criticized in the preceding sentences.","Система создаёт эффект и затем ссылается на него как на основание."],["It gives evidence that no educational practice ever influences conduct.","Финал предполагает как раз влияние практики."],["It limits the criticism to an isolated error in the spelling of an educational rule.","Речь о причинном рассуждении, не орфографии."],["It establishes a natural cause for every behavior the author has described.","Такой безусловный природный вывод отвергается."]]],
]);
r("virtue-standard","wollstonecraft","Chapter III: a common standard of virtue and reason",
"Wollstonecraft argues that moral virtue should rest on reason rather than on a demand for unquestioning compliance. To praise obedience as though it were sufficient for virtue would make a person's moral worth depend on yielding to another's will. Her argument is not that every act of cooperation is defective. It is that cooperation alone cannot tell us whether the action rests on understanding and judgment or merely on the inability to do otherwise.",[
["Central Ideas and Details",3,"Which choice best states the central distinction?",[["The appearance of compliance is not by itself evidence of the reasoned judgment required for moral virtue.","Внешнее подчинение не раскрывает основания поступка."],["Any action that benefits another person necessarily lacks moral worth.","Сотрудничество не объявлено недостатком само по себе."],["Reasoned judgment requires refusing every request made by another person.","Постоянное неповиновение не является условием разумности."],["A person's inability to choose establishes that the person's cooperation is virtuous.","Невозможность выбора названа альтернативой разумному решению."]]],
["Inferences",3,"Which case best illustrates the distinction?",[["Two people perform the same requested act, but only one has evaluated and accepted the reasons for doing it.","Одинаковое поведение может иметь разные основания."],["Two people disagree about an act because neither has heard what was requested.","Отсутствует сопоставление подчинения и осмысленного согласия."],["A person refuses a request solely to avoid thinking about its consequences.","Отказ без размышления не иллюстрирует разумную добродетель."],["A person accurately predicts a request before anyone has made it.","Предсказание не показывает основания сотрудничества."]]],
["Text Structure and Purpose",2,"Why does the author clarify that not every act of cooperation is defective?",[["To prevent a criticism of obedience as a sufficient criterion from being read as a rejection of cooperation itself.","Уточняется предмет критики: достаточность критерия."],["To concede that obedience and reasoned judgment have already been shown to be identical.","Они как раз различаются."],["To replace the argument about moral reasoning with an argument about physical ability.","Моральная тема сохраняется."],["To show that all requests deserve automatic acceptance.","Автоматическое принятие противоречит требованию суждения."]]],
]);
r("exercise-mind","wollstonecraft","Chapters II–III: exercise of understanding and strength",
"Wollstonecraft draws attention to capacities that grow through exercise. An understanding repeatedly spared the work of judgment may remain underdeveloped, just as a body denied activity may remain weak. The analogy does not establish that thought and muscle are physically identical. It challenges the assumption that an observed weakness must precede the conditions in which it appears. In some cases, those conditions may be part of the explanation rather than a response to an independently fixed limitation.",[
["Central Ideas and Details",3,"What is the main point?",[["Restricted opportunities for exercise may help explain a weakness that is wrongly treated as an original fixed condition.","Недостаток практики может быть причиной, а не следствием слабости."],["Mental and physical capacities always develop at exactly the same measurable rate.","Тождество скоростей не следует из аналогии."],["Any observed weakness proves that opportunities for development were unlimited.","Текст предлагает противоположную возможность."],["The capacity for judgment develops fully regardless of whether it is ever used.","Развитие связывается с упражнением."]]],
["Inferences",3,"Which observation would most strongly support the proposed explanation?",[["People given sustained opportunities to make and assess decisions develop abilities previously described as beyond their reach.","Изменение условий сопровождается развитием считавшейся невозможной способности."],["People prevented from making decisions continue to have little experience in making them.","Это совместимо с объяснением, но не так прямо показывает развитие."],["Observers use the same term for a mental weakness and an unrelated physical injury.","Совпадение терминов не подтверждает механизм."],["A group develops stronger muscles while receiving no additional opportunities to reason.","Так не проверяется развитие суждения от его упражнения."]]],
["Text Structure and Purpose",2,"What function does the analogy with the body serve?",[["It makes a developmental explanation of intellectual weakness easier to consider.","Знакомая роль упражнения помогает понять умственное развитие."],["It proves that all intellectual differences can be measured by muscle strength.","Такое тождество специально исключено."],["It supplies an exception showing that opportunities never affect understanding.","Аналогия поддерживает возможность влияния возможностей."],["It defines judgment as a purely involuntary bodily movement.","Такого определения нет."]]],
]);
r("pier-glass","eliot","Middlemarch, Chapter XXVII: the scratched pier-glass analogy",
"In Middlemarch, a narrator imagines fine scratches on a polished surface. When a candle is brought near, the scratches appear to form a pattern centered on its reflection. The marks were not arranged for that observer; the light gives them an apparent organization. The image becomes an analogy for self-centered interpretation: events that have independent causes can seem to converge on a person who treats a private standpoint as the organizing principle of the world.",[
["Central Ideas and Details",3,"Which choice best captures the analogy's central point?",[["A viewpoint can make independently existing details appear organized around the observer.","Центр видимого рисунка создаётся точкой освещения, не историей царапин."],["Events acquire independent causes only after someone stops observing them.","Причины существуют независимо от частной перспективы."],["A person can determine the actual cause of every event simply by finding a visible pattern.","Видимый порядок может быть эффектом точки зрения."],["The scratches physically rearrange themselves in response to the observer's wishes.","Перестраивается впечатление, а не расположение царапин."]]],
["Inferences",3,"Which example most closely parallels the error described?",[["A resident assumes that several unrelated neighborhood decisions were all made primarily in response to the resident's own concerns.","Независимые события ошибочно сводятся к личному центру."],["A resident checks meeting records before deciding why a neighborhood policy changed.","Это проверка причин, а не подмена их личной перспективой."],["A resident recognizes that two similar events had different documented causes.","Такой вывод как раз сохраняет независимость причин."],["A resident notices a policy change that directly names the resident as its intended beneficiary.","Здесь связь подтверждена, а не выведена из эгоцентричного впечатления."]]],
["Text Structure and Purpose",3,"Why does the text state that the marks were not arranged for the observer?",[["To distinguish the pattern's apparent center from the independent origin of its components.","Это необходимое различие для переноса аналогии на события."],["To establish that the polished surface contains no real scratches.","Реальность царапин не отрицается."],["To identify the person who intentionally organized every scratch into a circle.","Именно такую намеренную организацию текст исключает."],["To show that the candle has no effect on the appearance of the surface.","Свет меняет видимый порядок."]]],
]);
r("key-mythologies","eliot","Middlemarch: Casaubon's Key to All Mythologies and scholarly isolation",
"Casaubon seeks a comprehensive key to mythology, but the grandeur of the projected work does not establish the adequacy of its methods. His resistance to newer scholarship leaves an ambitious scheme detached from developments that might require it to change. The contrast exposes a difficulty in judging intellectual work by its intended scope alone. A project can promise to organize an enormous field while lacking a means of revising the assumptions on which that organization depends.",[
["Central Ideas and Details",3,"Which choice best summarizes the text?",[["A scholarly project's sweeping ambition cannot compensate for methods insulated from relevant criticism and developments.","Масштаб замысла не заменяет пересмотр оснований."],["A scholarly project becomes methodologically sound whenever it covers enough separate subjects.","Достаточность масштаба как раз оспаривается."],["New scholarship is relevant only to projects that have no organizing assumptions.","Новое знание может потребовать изменения существующих допущений."],["Any effort to organize a large field necessarily prevents intellectual revision.","Критикуется конкретная закрытость, а не любой большой замысел."]]],
["Inferences",3,"Which change would most directly address the stated difficulty?",[["Submit the scheme's basic assumptions to findings from scholarship it has previously excluded.","Это устраняет изоляцию от потенциально корректирующих данных."],["Expand the list of subjects while keeping all basic assumptions beyond examination.","Масштаб увеличится, но названная проблема сохранится."],["Describe the intended work in more impressive language without altering its research process.","Риторическая грандиозность не меняет метод."],["Treat the time already spent on the project as proof that no revision is needed.","Затраченные усилия не проверяют адекватность оснований."]]],
["Text Structure and Purpose",2,"What is the function of the final sentence?",[["It generalizes the methodological problem illustrated by the particular projected work.","Частный пример превращается в общий критерий оценки проекта."],["It provides a list of mythological figures analyzed successfully by Casaubon.","Такого списка и оценки успеха нет."],["It concedes that scope alone proves the project's value.","Именно это текст отрицает."],["It shifts from scholarly work to the financial cost of publishing books.","Тема методов исследования не меняется."]]],
]);
r("lydgate-network","eliot","Middlemarch: Lydgate's medical ambitions and provincial relationships",
"Lydgate enters provincial medical life with ambitions shaped by scientific inquiry, yet his professional choices also depend on local alliances, reputations, and obligations. His knowledge does not operate in an empty social space. The narrative complicates a simple opposition between a brilliant individual and an ignorant town: even a reformer must act through institutions and relationships that can both enable and constrain the reform. Intellectual purpose alone does not determine how a career develops.",[
["Central Ideas and Details",2,"Which statement best conveys the central idea?",[["Scientific ambition is realized through social circumstances that can support it as well as limit it.","Отношения и институты имеют двоякую роль в карьере."],["A reformer's scientific knowledge makes local institutions irrelevant to professional choices.","Текст подчёркивает их значение."],["Every provincial relationship inevitably destroys any possibility of medical improvement.","Они могут и помогать реформе."],["The narrative attributes every professional difficulty exclusively to a lack of scientific intelligence.","Карьера объясняется не только умственными качествами."]]],
["Inferences",3,"Which information would be most useful for analyzing Lydgate's decisions under this account?",[["How access to patients and professional cooperation depends on the local relationships surrounding his proposed reforms.","Это показывает посредничество социальных условий между целью и действием."],["Whether the spelling of his name changes in different editions of the novel.","Это не объясняет профессиональные решения."],["How many scientific terms he can define when removed from all practical circumstances.","Изолированное знание исключает названный социальный механизм."],["Whether every resident holds exactly the same opinion about all medical questions.","Полное единомыслие не требуется для анализа конкретных связей."]]],
["Text Structure and Purpose",3,"What does the phrase 'an empty social space' help emphasize?",[["That knowledge affects action within a network of relationships rather than under socially neutral conditions.","Образ подчёркивает неизолированность знания."],["That the town contains no institutions through which a physician could work.","Институты прямо названы значимыми."],["That scientific inquiry is absent from Lydgate's ambitions.","Научная мотивация указана в первом предложении."],["That the narrator considers all relationships equally unimportant.","Текст посвящён их существенному влиянию."]]],
]);
r("dorothea-cottages","eliot","Middlemarch, Book I: Dorothea's interest in cottages and practical improvement",
"Dorothea's interest in improving cottages gives a practical direction to aspirations that others may dismiss as excessive seriousness. Her concern is not exhausted by the appearance of an ideal dwelling; she wants arrangements that change how people actually live. Yet enthusiasm for improvement does not automatically supply all the knowledge needed to design it. The episode makes room for both the generosity of a purpose and the need to connect that purpose to an informed understanding of particular conditions.",[
["Central Ideas and Details",2,"Which choice best states the text's main idea?",[["A generous reforming aim deserves recognition while still requiring practical knowledge to become effective.","Мотив и достаточное знание различены без обесценивания мотива."],["A reforming aim is worthless whenever its proponent lacks complete technical knowledge.","Ценность намерения не отменяется недостатком знаний."],["The appearance of a dwelling is the only concern motivating Dorothea's interest.","Её интерес связан с реальными условиями жизни."],["Enthusiasm alone guarantees that every proposed improvement will work as intended.","Текст прямо исключает такую гарантию."]]],
["Inferences",3,"Which response to Dorothea's proposal best fits this interpretation?",[["Take the intended benefit seriously while investigating residents' needs and the feasibility of the design.","Так сочетаются признание цели и проверка условий."],["Dismiss the proposal solely because its author expresses unusually strong concern.","Это повторяет поверхностное пренебрежение серьёзностью."],["Approve every detail without inquiry because the motive is generous.","Благой мотив не заменяет техническую проверку."],["Evaluate the plan only by its visual elegance, without asking how residents would use it.","Практическая жизнь — существенная часть цели."]]],
["Text Structure and Purpose",2,"What is the effect of the sentence beginning 'Yet enthusiasm'?",[["It qualifies the practical sufficiency of the aspiration without denying its generosity.","Оговорка касается реализации, а не отрицания щедрого намерения."],["It proves that the earlier account of Dorothea's concern was insincere.","Неосведомлённость не равна неискренности."],["It replaces a concern for residents with an exclusive concern for decorative appearance.","Такого изменения цели нет."],["It establishes that no improvement can ever be informed by experience.","Наоборот, требуется знание конкретных условий."]]],
]);

r("variation-use","darwin","Chapter I: variation under domestication and selection",
"Darwin distinguishes the occurrence of variation from the preservation of particular variations by breeders. A breeder need not have caused a useful difference in order to increase its prevalence by choosing which organisms reproduce. This distinction separates the origin of an available difference from a process that changes how common it becomes. An account of selective breeding is therefore incomplete if it assumes that every characteristic favored by a breeder must first have been deliberately produced by that breeder.",[
["Central Ideas and Details",2,"Which distinction is central to the text?",[["Causing a variation and increasing its frequency through reproductive choices are different processes.","Происхождение различия отделено от его распространения отбором."],["A breeder can preserve a variation only by directly causing its first appearance.","Это именно отвергаемое допущение."],["Every variation becomes more common regardless of which organisms reproduce.","Репродуктивный выбор влияет на частоту."],["Deliberately choosing parents prevents any inherited characteristic from changing in frequency.","Текст говорит о возможном увеличении частоты."]]],
["Inferences",3,"Which observation would most clearly illustrate the distinction?",[["An unexpected trait appears in a flock, and breeders subsequently make it common by selecting birds that carry it.","Первое появление незапланировано, дальнейшее распространение избирательно."],["A breeder announces an interest in a trait but never observes it or selects any organisms.","Нет показанного сохранения уже возникшего различия."],["A trait appears and disappears before any organism carrying it can reproduce.","Так не иллюстрируется повышение частоты через выбор родителей."],["Every bird changes in the same way immediately after hearing a breeder's instruction.","Это не описанный механизм отбора наследственных вариантов."]]],
["Text Structure and Purpose",3,"What role does the last sentence play?",[["It identifies a mistaken assumption that the preceding distinction allows the reader to reject.","Финал показывает ошибку смешения причины возникновения и отбора."],["It establishes that breeders always know the exact causes of new variations.","Причины возникновения могут быть им неизвестны."],["It denies that selective breeding can alter the characteristics of a population.","Изменение распространённости признака как раз допускается."],["It shifts from heredity to the financial cost of animal husbandry.","Финансовой темы нет."]]],
]);
r("struggle-broad","darwin","Chapter III: struggle for existence used in a large and metaphorical sense",
"Darwin warns that the struggle for existence should be understood broadly. A plant at the edge of a desert may depend on moisture rather than engage in visible combat with another plant. Survival also depends on relationships with other organisms and on producing offspring. The phrase gathers these dependencies under one heading. Reading it only as a description of direct fighting would exclude many of the conditions that the argument treats as relevant to the persistence of a population.",[
["Central Ideas and Details",2,"Which choice best captures the main idea?",[["The struggle for existence includes environmental and reproductive dependencies beyond direct physical conflict.","Термин охватывает условия сохранения, а не только схватку."],["Plants encounter no struggle because they cannot engage in physical combat.","Пример растения расширяет понятие борьбы."],["Reproduction is unrelated to whether a population persists.","Потомство включено в релевантные зависимости."],["Only competition between members of different species can influence survival.","Среди факторов названа и влага."]]],
["Inferences",3,"Which case most clearly falls within the broad usage described?",[["A flowering plant produces fewer offspring when the insects that transfer its pollen become scarce.","Зависимость размножения от другого организма входит в широкое понятие."],["Two descriptions use different words for the same plant without reporting any biological difference.","Лексическое различие не является условием выживания или размножения."],["An illustration makes a plant look larger without changing any of its circumstances.","Изменение рисунка не влияет на сохранение популяции."],["An observer assumes survival is guaranteed because no animals are seen attacking the plant.","Это ошибочное узкое понимание, а не пример зависимости."]]],
["Text Structure and Purpose",2,"Why is the desert plant introduced?",[["To provide a case that the broad meaning includes but a combat-only meaning would miss.","Пример демонстрирует недостаточность буквального толкования."],["To show that moisture is irrelevant once plants begin to reproduce.","Зависимость от влаги подчёркивается."],["To establish that desert plants never interact with other organisms.","Такого абсолютного утверждения нет."],["To identify a species Darwin considers incapable of persisting.","Конкретный вид и невозможность сохранения не названы."]]],
]);
r("geological-record","darwin","Chapter IX: imperfection of the geological record",
"A sequence of fossils is not a continuous recording of every population that ever lived. Darwin emphasizes the conditions required for remains to be preserved and for the containing strata to survive and become accessible. A missing intermediate in a collected series can therefore have more than one explanation. It may bear on a proposed history of organisms, but its significance depends partly on how complete a record the processes of preservation could reasonably have supplied.",[
["Central Ideas and Details",3,"Which statement best expresses the central idea?",[["An absence in the fossil record must be interpreted in light of the record's selective preservation and accessibility.","Пробел оценивается с учётом механизма формирования свидетельств."],["Every proposed evolutionary history is confirmed whenever any fossil is missing.","Пробел не объявлен автоматическим подтверждением."],["The fossil record includes a complete sample of all organisms that have ever lived.","Именно непрерывность записи отрицается."],["Preservation conditions have no bearing on the interpretation of a collected fossil series.","Текст делает их существенно важными."]]],
["Inferences",3,"Which finding would make a particular absence more informative?",[["The relevant interval is represented by unusually continuous deposits known to preserve the type of organism in question.","При более полном ожидаемом наблюдении отсутствие сильнее различает объяснения."],["Most deposits from the relevant interval have been destroyed or remain inaccessible.","Это увеличивает альтернативное объяснение пробела."],["The organisms in question rarely leave remains capable of preservation.","Низкая сохраняемость делает отсутствие менее показательным."],["Collectors have not yet examined the formations where the intermediate would most likely occur.","Неполный поиск ослабляет значение отсутствия."]]],
["Text Structure and Purpose",3,"What is the function of the second sentence?",[["It explains mechanisms that limit the completeness assumed by an overly literal reading of the record.","Сохранение, выживание пластов и доступность объясняют избирательность."],["It proves that no inference about the past can ever use fossils.","Ограничения не отменяют всех выводов."],["It introduces a continuous recording device that Darwin used to observe extinct organisms.","Подобного устройства нет."],["It establishes that all collected fossils belong to one uninterrupted layer.","Такой стратиграфической полноты текст не утверждает."]]],
]);
r("classification-affinity","darwin","Chapter XIII: classification, affinity and genealogy",
"A classification can group organisms by a conspicuous shared feature, but such a feature need not be the best guide to their relationships. Similar ways of living may favor similar structures in different lineages. Darwin's discussion instead gives weight to patterns of affinity interpreted through descent. A useful classificatory character may consequently be one whose significance is not obvious from its immediate practical function. The most visually striking resemblance and the most informative resemblance need not coincide.",[
["Central Ideas and Details",3,"Which statement best conveys the main point?",[["The value of a resemblance for classification depends on what it reveals about relationships, not simply on its conspicuousness.","Диагностическая значимость отличается от заметности признака."],["Every organism with a similar way of living must belong to the same immediate lineage.","Сходные условия могут действовать в разных линиях."],["A character becomes irrelevant to classification whenever its practical function is unclear.","Неочевидность функции не исключает ценности для классификации."],["The most striking resemblance always provides the most reliable evidence of descent.","Совпадение этих критериев не гарантировано."]]],
["Inferences",3,"Which evidence would most weaken an argument based only on a shared conspicuous structure?",[["The structure independently appears in several otherwise distinct lineages exposed to similar environmental demands.","Независимое возникновение ослабляет вывод о близком происхождении."],["The structure is easy for observers to notice without special equipment.","Заметность не проверяет общность происхождения."],["The structure performs a useful function in both of the organisms being compared.","Полезность сама по себе не исключает независимого возникновения."],["The two organisms have been pictured together in an illustrated field guide.","Соседство в книге не является генеалогическим свидетельством."]]],
["Text Structure and Purpose",2,"How does the last sentence relate to the rest?",[["It condenses the distinction between visual prominence and evidentiary importance.","Финал кратко формулирует различие двух критериев."],["It retracts the possibility that some resemblances are useful.","Полезность некоторых сходств сохраняется."],["It identifies a particular organism whose ancestry has been proved conclusively.","Конкретного организма и окончательного доказательства нет."],["It shifts the discussion from relationships to the beauty of illustrations.","Речь по-прежнему об информативности признаков."]]],
]);
r("island-dispersal","darwin","Chapter XII: oceanic islands and geographical distribution",
"Darwin considers not only the physical conditions on islands but also the means by which organisms could reach them. A habitat may appear suitable for a group that is nevertheless absent because crossing the intervening sea presents a barrier. Distribution therefore records opportunities for arrival as well as opportunities for survival after arrival. An explanation confined to present-day climate would miss a historical condition that can help account for differences between otherwise comparable places.",[
["Central Ideas and Details",2,"Which choice best states the main idea?",[["An organism's absence from a suitable habitat may reflect limits on reaching it rather than inability to survive there.","Пригодность среды и возможность расселения — разные условия."],["Present-day climate fully explains every difference between island populations.","Климатического объяснения недостаточно."],["Organisms that cross a sea must necessarily survive in every habitat they reach.","Прибытие и дальнейшее выживание не тождественны."],["Any two islands with similar weather must contain identical groups of organisms.","История прибытия может различаться."]]],
["Command of Evidence (Textual)",3,"Which finding would most directly support the distinction?",[["A group missing from a remote island survives there after documented human introduction.","После устранения барьера прибытия оказывается возможным выживание."],["A group missing from an island also fails to survive there after repeated introductions.","Это скорее поддержит непригодность условий для данной группы."],["Two islands differ in both climate and all known opportunities for arrival.","Такой случай не выделяет роль расселения при сходной среде."],["A map uses the same color for islands with similar average annual temperatures.","Оформление карты не является биологическим свидетельством."]]],
["Text Structure and Purpose",2,"What does the contrast between arrival and survival clarify?",[["Two distinct requirements that must be considered when explaining an observed distribution.","Показываются разные звенья формирования распространения."],["A reason to ignore the history of all island populations.","История как раз вводится в объяснение."],["A claim that all remote islands are equally unsuitable for life.","Пригодность некоторых островов признаётся."],["Two different names for exactly the same ecological event.","Прибытие и сохранение различены."]]],
]);
r("price-value","smith","Book I, Chapter IV: value in use and value in exchange",
"Smith distinguishes usefulness from exchange value by noting that an item essential to life can command little in exchange, while another with comparatively little practical use can command a great deal. The contrast does not deny that useful things matter. It warns against treating two senses of value as interchangeable. An explanation of what people give up to obtain an object cannot simply be read off from how indispensable that object seems in ordinary life.",[
["Central Ideas and Details",2,"Which distinction is most important to the passage?",[["An object's practical importance and the amount it commands in exchange need not vary together.","Полезность и обменная ценность могут расходиться."],["Objects essential to life have no importance of any kind.","Это прямо исключённое толкование."],["A high exchange value establishes that an object is necessary for survival.","Именно такой перенос между смыслами неверен."],["Practical use and exchange value are two interchangeable names for the same measure.","Два значения различаются."]]],
["Inferences",3,"Which conclusion is best supported?",[["Showing that an item is highly useful is insufficient, by itself, to explain its exchange value.","Нужны основания сверх жизненной важности вещи."],["No useful object can ever have a high exchange value.","Расхождение не устанавливает абсолютную несовместимость."],["The prices of all nonessential objects must be identical.","О сравнении всех несущественных предметов ничего не следует."],["Exchange eliminates every distinction between useful and unnecessary objects.","Виды ценности остаются различными."]]],
["Text Structure and Purpose",2,"What is the function of the third sentence?",[["It blocks an overstatement that could arise from confusing a distinction about value with a denial of usefulness.","Различение критериев не превращается в отрицание важности полезного."],["It withdraws the contrast between usefulness and exchange value.","Контраст сохраняется и уточняется."],["It introduces a numerical formula that predicts the price of every commodity.","Универсальной формулы нет."],["It argues that ordinary language has only one possible meaning of value.","Текст прямо выделяет два смысла."]]],
]);
r("unintended-tools","smith","Book I, Chapter I: invention of machinery under division of labour",
"Smith links some improvements in machinery to workers' sustained attention to a limited task. Someone who repeatedly performs one operation may notice a way to simplify it that escapes a person constantly shifting among unrelated activities. The argument concerns an opportunity created by focused practice; it does not claim that all invention comes from specialized workers. Nor does it imply that an improvement must have been planned by the person who originally divided the work.",[
["Central Ideas and Details",2,"Which choice best states the main idea?",[["Repeated attention to a limited operation can create opportunities for improvements not necessarily planned in advance.","Практический фокус помогает заметить усовершенствование."],["Every invention must be designed by the person responsible for organizing an entire workplace.","Авторство организатора не требуется."],["Constantly changing tasks is the only way to notice possible mechanical improvements.","Описан иной механизм — устойчивое внимание к операции."],["Specialization guarantees that each worker will invent a new machine.","Возможность не является гарантией для каждого."]]],
["Inferences",3,"Which observation would most directly support Smith's proposed mechanism?",[["A worker devises a shortcut after recognizing a recurring difficulty in the single operation the worker performs daily.","Повторение помогает выделить устранимую трудность."],["An owner purchases a machine without consulting anyone who performs the operation.","Происхождение из практического внимания работника не показано."],["A factory increases its size but makes no recorded change in any operation.","Рост размера не подтверждает механизм изобретения."],["A worker moves among unrelated tasks and never repeats any of them.","Отсутствует условие устойчивого наблюдения."]]],
["Text Structure and Purpose",3,"What is the purpose of the last two sentences?",[["To limit the claim's scope by distinguishing a possible source of invention from exclusive or intentional origins.","Снимаются чрезмерные выводы об исключительности и заранее заданном плане."],["To argue that focused practice has no connection with mechanical improvement.","Оговорки не отменяют основную связь."],["To identify the original organizer as the inventor of all later improvements.","Именно обязательность такого авторства исключается."],["To replace the explanation with a universal law about every worker's behavior.","Универсальная гарантия не формулируется."]]],
]);
r("invisible-cooperation","smith","Book I, Chapter I: cooperation in producing ordinary goods",
"An ordinary manufactured article can depend on the work of many people who never meet its final user. Smith's account traces familiar goods through the occupations and exchanges required to produce them. The point is not that every participant understands the entire chain. Coordinated results can emerge through many limited contributions, and the apparent simplicity of a finished object can obscure the complexity of the cooperation on which it depends.",[
["Central Ideas and Details",2,"What is the central idea?",[["A familiar finished object can embody extensive cooperation even when participants know only their own parts.","Простота вещи скрывает распределённый труд и обмен."],["Every person contributing to an article must understand its entire production chain.","Полное знание каждого участника не требуется."],["Finished goods become simpler only when all exchanges between occupations cease.","Текст не связывает простоту с прекращением обменов."],["A user can identify all contributors merely by examining an object's visible surface.","Внешний вид может скрывать сложность."]]],
["Inferences",3,"Which finding would be most consistent with the account?",[["Workers who cannot name one another nonetheless supply complementary inputs that reach the same finished product.","Личное знакомство не требуется для совместного результата."],["A product's ordinary appearance proves it was made without specialized contributions.","Обычность вида не исключает разделённого труда."],["A missing contributor's input is always replaced instantly without affecting production.","Такая полная взаимозаменяемость не следует из сотрудничества."],["The final user must personally direct every exchange that precedes production.","Управление пользователем не установлено."]]],
["Text Structure and Purpose",2,"Why does the passage focus on an ordinary article rather than an exceptional invention?",[["To reveal hidden complexity in something readers might initially regard as simple.","Повседневность усиливает несоответствие видимой простоты и скрытой кооперации."],["To show that unusual inventions never involve any cooperation.","Об исключительных изобретениях такого вывода нет."],["To establish that all ordinary objects require exactly the same production chain.","Тождество цепочек не утверждается."],["To argue that goods should be evaluated only by their outward appearance.","Внешний вид назван потенциально обманчивым."]]],
]);
r("habit-reasons","mill","Chapter II: understanding the grounds of a received opinion",
"Mill distinguishes accepting a conclusion from understanding the strongest objections to it. A person may repeat convincing arguments for a belief yet misunderstand the dispute if the opposing case is known only through a weak version supplied by allies. Examining an objection in a form that its proponents would recognize does not require accepting it. It makes the grounds of one's own judgment answerable to the actual disagreement rather than to a conveniently simplified substitute.",[
["Central Ideas and Details",3,"Which choice best states the central idea?",[["Understanding a dispute requires engaging with a credible opposing case rather than merely repeating a favored conclusion.","Сильное возражение проверяет основания собственного суждения."],["A person must adopt every objection in order to understand it accurately.","Понимание специально отделено от принятия."],["An opponent's case is best understood when rewritten solely by people who reject it.","Слабая версия от союзников названа проблемой."],["A conclusion becomes true whenever its defenders can repeat the same arguments fluently.","Беглое повторение не является критерием истины."]]],
["Inferences",3,"Which practice would best address the limitation identified?",[["Before responding, state an objection in terms its informed proponents regard as accurate.","Это заменяет удобную подмену действительной позицией."],["Choose the least plausible formulation of an objection to make a rebuttal easier.","Так сохраняется названная подмена."],["Treat exposure to any opposing argument as automatic abandonment of one's position.","Текст различает рассмотрение и согласие."],["Measure understanding only by how quickly a favored conclusion can be repeated.","Скорость повторения не проверяет понимание спора."]]],
["Text Structure and Purpose",2,"What does the third sentence clarify?",[["That fair consideration of an objection is compatible with continuing to reject it.","Точное понимание не обязывает принять возражение."],["That all disagreements must end with both sides adopting the same belief.","Обязательное согласие не предполагается."],["That allies are always unable to describe an opposing position accurately.","Критикуется слабое представление, не любой союзник."],["That a conveniently simplified substitute is preferable to the actual dispute.","Текст утверждает противоположное."]]],
]);
r("choice-faculties","mill","Chapter III: choice, judgment and development of individuality",
"Mill values choosing a way of life partly because choice exercises capacities that passive conformity can leave unused. Someone who adopts a practice after examining alternatives may arrive at the same outward conduct as a person who follows custom without reflection. The identical result does not make the processes equivalent. On this account, the value of choosing includes the development of perception and judgment, not just the possibility of producing an unusual decision.",[
["Central Ideas and Details",2,"Which idea is most central?",[["Choosing can have developmental value even when it leads to the same conduct as conformity.","Одинаковый итог не отменяет упражнения суждения в процессе выбора."],["A choice has value only if it results in behavior no one has previously adopted.","Необычность результата не является необходимой."],["Following custom always requires more reflection than considering alternatives.","Текст не устанавливает такого соотношения."],["Identical outward actions necessarily reflect identical uses of judgment.","Эквивалентность процессов прямо отрицается."]]],
["Inferences",3,"Which comparison would best illustrate the distinction?",[["Two students follow the same study routine, but only one has compared options and can explain why the routine fits their needs.","Результат совпадает, основания и процесс выбора различаются."],["Two students choose different routines solely because a random drawing assigns them different schedules.","Различие итогов без упражнения суждения не иллюстрирует главный тезис."],["One student considers alternatives and another student considers the same alternatives equally carefully.","Так не сравниваются выбор и нерефлексивное следование."],["Two students are prevented from choosing and are assigned identical routines.","В обоих случаях отсутствует сравниваемый активный процесс."]]],
["Text Structure and Purpose",2,"Why does the text allow that both people may behave identically?",[["To isolate the value of the decision process from the novelty of its outcome.","Сохранение результата позволяет выделить значение самого выбора."],["To concede that reflection has no possible effect on personal development.","Развитие суждения является названной ценностью."],["To establish that every customary practice is the best available option.","О превосходстве всех обычаев не говорится."],["To show that examining alternatives necessarily prevents a decision.","Рассмотрение альтернатив приводит к выбору."]]],
]);
r("despot-custom","mill","Chapter III: custom, improvement and individuality",
"Mill worries about custom becoming a final authority rather than a source of experience that people may examine. A practice's endurance can give reasons for considering it seriously, but endurance alone cannot establish that no alternative could improve upon it. His concern is thus compatible with learning from the past. It arises when accumulated experience is treated as closing inquiry instead of providing material with which judgment can work.",[
["Central Ideas and Details",3,"Which statement best expresses the main idea?",[["Past practice can inform judgment without acquiring an unquestionable authority over future choices.","Опыт традиции полезен как основание для рассмотрения, а не запрета проверки."],["Every long-standing practice should be rejected solely because it has endured.","Учиться у прошлого не запрещается."],["A practice's continued existence proves that all possible alternatives are inferior.","Достаточность такого доказательства оспаривается."],["Judgment can use past experience only by treating it as a final command.","Информационная и окончательно повелевающая роли различаются."]]],
["Inferences",3,"Which response to a long-standing rule best accords with the text?",[["Investigate why the rule endured while remaining open to evidence that another arrangement would work better.","Совмещаются внимание к опыту и открытость пересмотру."],["Assume that the rule's age removes any need to examine its effects.","Так длительность превращается в окончательный авторитет."],["Ignore all evidence about past results because the rule is traditional.","Это исключает признанное обучение у прошлого."],["Allow alternatives only if they reproduce every detail of the established rule.","Такое условие фактически закрывает проверку альтернатив."]]],
["Text Structure and Purpose",2,"What does the third sentence accomplish?",[["It prevents the critique of unquestionable custom from being mistaken for a rejection of historical experience.","Оговорка отделяет критическое использование прошлого от отказа от него."],["It establishes that past practices have never yielded any useful information.","Полезность опыта прямо допускается."],["It introduces a chronological account of one particular custom's origin.","Истории конкретного обычая нет."],["It reverses the claim that inquiry should remain open.","Открытость остаётся центральной нормой."]]],
]);
r("cost-life","thoreau","Economy: the cost of a thing measured in life",
"Thoreau proposes assessing a possession not only by its money price but also by the portion of life exchanged for it. Earning, maintaining, and arranging one's affairs around an object can impose costs that a purchase receipt does not display. His calculation challenges an account of prosperity based solely on the quantity owned. Acquiring more may reduce freedom if the acquisition requires commitments that the owner would otherwise have chosen to avoid.",[
["Central Ideas and Details",2,"Which choice best states the central idea?",[["A possession's cost includes the time and commitments required to acquire and sustain it.","Цена вещи расширяется до затрат жизни и обязательств."],["A low purchase price guarantees that an object demands no further effort.","Последующие затраты могут не отражаться в чеке."],["The quantity of possessions is a sufficient measure of every person's freedom.","Этот критерий подвергается сомнению."],["Any possession necessarily makes its owner less free in exactly the same way.","Текст говорит о возможном эффекте при определённых обязательствах."]]],
["Inferences",3,"Which comparison best applies this conception of cost?",[["Two equally priced objects differ substantially in the hours their owners must spend maintaining and paying for them.","Одинаковая денежная цена скрывает разную жизненную стоимость."],["Two objects have the same color but are advertised in different newspapers.","Такие признаки не раскрывают затрат времени и обязательств."],["A buyer chooses the more expensive object because every higher price guarantees greater freedom.","Цена не является гарантией свободы."],["An owner counts possessions without considering how any were acquired or maintained.","Это как раз недостаточный способ оценки."]]],
["Text Structure and Purpose",2,"What purpose does the reference to a receipt serve?",[["It highlights the limits of a readily visible monetary measure.","Чек делает наглядным различие денежной и полной стоимости."],["It establishes that written records are never accurate about money spent.","Точность суммы в чеке не оспаривается."],["It identifies the only evidence needed to measure a person's prosperity.","Текст показывает неполноту такого свидетельства."],["It shifts the subject to how receipts were printed in the nineteenth century.","Технология печати не обсуждается."]]],
]);
r("ice-observation","thoreau","The Pond in Winter: measuring the depth of Walden",
"Reports of a pond's extraordinary depth can persist when few people have attempted to measure it. Thoreau responds to the reputation of Walden by making a sounding rather than merely exchanging one confident story for another. The episode contrasts the authority of repeated local belief with the authority of an inquiry directed at the particular claim. Its significance lies less in replacing wonder with indifference than in showing that close investigation can alter the terms on which wonder rests.",[
["Central Ideas and Details",2,"Which claim best summarizes the text?",[["A direct measurement can revise a persistent belief without requiring an end to interest in its subject.","Проверка глубины уточняет основание удивления, а не уничтожает интерес."],["A widely repeated report becomes accurate whenever it concerns a familiar local place.","Повторяемость противопоставлена проверке."],["Investigation of a natural feature necessarily makes that feature uninteresting.","Такое отождествление прямо отвергается."],["The only way to challenge an exaggerated claim is to propose a more dramatic story.","Измерение заменяет обмен историями."]]],
["Inferences",3,"Which finding would most directly support the reliability of the inquiry?",[["Independent soundings at documented locations produce consistent results with a method capable of reaching the pond bottom.","Проверяемая процедура и согласованные измерения поддерживают надёжность."],["Several residents repeat the same depth estimate without describing how it was obtained.","Это воспроизводит авторитет повторения."],["The pond looks darker on cloudy days than it does in sunlight.","Цвет поверхности не измеряет заявленную глубину."],["A more dramatic account of the pond attracts more visitors than a measured one.","Популярность рассказа не проверяет результат."]]],
["Text Structure and Purpose",3,"What does the final sentence qualify?",[["The assumption that correcting a belief must remove the value of attentive engagement with nature.","Исправление легенды не исключает нового, более осмысленного удивления."],["The assumption that a sounding is a method of measuring water depth.","Назначение измерения не ставится под сомнение."],["The claim that local beliefs can persist without direct investigation.","Эта возможность сохраняется."],["The idea that repeated stories and measurements use different forms of evidence.","Различие видов основания остаётся в силе."]]],
]);
r("transparent-observer","emerson","Nature, Chapter I: altered perception in the woods",
"Emerson's account of being in the woods gives unusual weight to a change in the observer. Familiar distinctions of status and private preoccupation recede, and the scene becomes available to a more expansive attention. The passage need not be read as a report that the physical landscape has suddenly changed. Its force depends on the possibility that a familiar setting can take on a different significance when the habits through which it is perceived are interrupted.",[
["Central Ideas and Details",3,"Which choice best conveys the text's main idea?",[["A change in the observer's attention can transform the experienced significance of an otherwise familiar landscape.","Меняется способ восприятия, а не обязательно сама среда."],["A landscape can affect a person only by undergoing an abrupt physical alteration.","Такое необходимое условие отвергается."],["Social status becomes more important to Emerson whenever he enters the woods.","Различия статуса отступают."],["Familiar settings are incapable of producing any experience not previously encountered.","Текст описывает новое значение знакомого окружения."]]],
["Inferences",3,"Which observation best fits the interpretation?",[["A person returns to an unchanged path but notices relationships previously obscured by persistent private worries.","Изменение внимания открывает ранее не замеченные связи."],["A path is replaced by a building, and the visitor concludes that no physical change occurred.","Это отрицание материального изменения, а не новая перспектива на прежнее."],["A visitor attends only to social rank and finds that the woods reproduce every prior concern.","Так сохраняются именно те привычки, которые в тексте прерываются."],["An observer assumes that noticing a new color proves the entire landscape was created that morning.","Новизна восприятия не доказывает новизну объекта."]]],
["Text Structure and Purpose",2,"What is the function of the third sentence?",[["It distinguishes a perceptual interpretation from an unnecessarily literal claim about the landscape.","Уточняется, где происходит значимое изменение."],["It denies that Emerson describes any change in experience.","Перемена опыта остаётся центральной."],["It supplies a measurement of the scene's physical transformation.","Измерений нет, буквальная перемена не требуется."],["It argues that attention has no role in encounters with familiar places.","Роль внимания подчёркивается."]]],
]);
r("commodity-beauty","emerson","Nature, Chapters II–III: Commodity and Beauty",
"Emerson discusses nature both as a source of practical provision and as an object of aesthetic experience. These approaches concern the same world but select different relations to it. A tree can supply material without its usefulness exhausting what a person may find valuable in seeing it. The distinction does not require a second, separate landscape for contemplation. It invites the reader to recognize that a single thing can participate in more than one meaningful form of experience.",[
["Central Ideas and Details",2,"Which statement best expresses the main idea?",[["The same natural object can have practical and aesthetic significance that are not reducible to one another.","Разные отношения к одному объекту не требуют двух объектов."],["A useful natural object loses every possibility of aesthetic significance.","Полезность не исчерпывает ценность дерева."],["Practical and aesthetic experience must concern physically separate landscapes.","Это условие прямо отвергнуто."],["A tree's appearance is relevant only when the tree cannot supply any material.","Такой зависимости между ценностями не установлено."]]],
["Inferences",3,"Which example best illustrates the distinction?",[["A person values a grove as a source of shade while also attending to patterns of light among its branches.","Один объект участвует в практическом и эстетическом опыте."],["A person concludes that a grove cannot be beautiful because its shade is useful.","Это ошибочно сводит виды значения к несовместимым."],["A person assumes that practical use and contemplation are different names for identical activities.","Различие отношений как раз сохраняется."],["A person discusses two imaginary forests without attributing any value to either.","Так не показаны две формы значения одного объекта."]]],
["Text Structure and Purpose",2,"Why does the author use a single tree as an example?",[["To make it clear that different kinds of value can attach to one and the same object.","Единичный пример удерживает тождество объекта при различии ценностей."],["To establish that trees are the only objects capable of aesthetic significance.","Исключительность деревьев не заявлена."],["To show that practical provision cannot be found in nature.","Практическая роль природы признаётся."],["To replace the distinction with a ranking of tree species by price.","Цены и ранжирование видов не обсуждаются."]]],
]);
r("elizabeth-letter","austen","Chapters XXXV–XXXVI: Darcy's letter and Elizabeth's reconsideration",
"After reading Darcy's letter, Elizabeth does not immediately accept every claim in it. She revisits earlier conversations and compares the account with details she had interpreted through her preference for Wickham. Her reconsideration exposes how an agreeable manner had influenced her judgment of credibility. The change is not simply a transfer of loyalty from one speaker to another. It involves recognizing that the evidence she already possessed had been arranged by a bias she had not previously acknowledged.",[
["Central Ideas and Details",3,"Which choice best states the main idea?",[["Elizabeth revises her judgment by reassessing both prior evidence and the preference that shaped her interpretation of it.","Меняются оценка фактов и осознание собственной предвзятости."],["Elizabeth accepts the letter solely because she now prefers every aspect of Darcy's manner.","Мгновенное принятие и простая смена симпатии исключены."],["The letter supplies every relevant fact, none of which Elizabeth had encountered before.","Она возвращается к уже известным деталям."],["Elizabeth concludes that an agreeable manner always guarantees truthful testimony.","Именно влияние привлекательной манеры подвергается проверке."]]],
["Inferences",3,"Which inference is best supported?",[["A judgment can change even without wholly new evidence if the person recognizes a bias in how existing evidence was weighed.","Переоценка прежних сведений способна изменить вывод."],["A person can correct bias only by refusing to consider any previous conversation.","Рассмотрение прежних разговоров — часть коррекции."],["A pleasant manner is sufficient reason to regard all contradictory evidence as irrelevant.","Это прежнее искажение, а не допустимый вывод."],["The discovery of bias proves that the opposite of every earlier belief must be true.","Требуется проверка, а не механическое обращение всех убеждений."]]],
["Text Structure and Purpose",2,"What is the purpose of the contrast in the fourth sentence?",[["To distinguish a reasoned reassessment from merely favoring a different person.","Контраст уточняет характер перемены в суждении."],["To show that no evidence contributes to Elizabeth's change of mind.","Работа с деталями прямо описана."],["To deny that Elizabeth ever favored Wickham.","Её прежняя симпатия названа причиной искажения."],["To establish that a letter is always more credible than a conversation.","Всеобщий приоритет письма не обоснован."]]],
]);
r("free-indirect","austen","Chapters I–III: social expectations, judgment and narrative irony",
"The opening world of Pride and Prejudice is full of confident judgments about other people's intentions. Families interpret arrivals, invitations, and manners through expectations about marriage and status. The narrative's irony allows such judgments to be heard without requiring the reader to accept them as neutral descriptions. What a community confidently calls obvious can therefore reveal the community's priorities as much as it reveals the intentions of the person being discussed.",[
["Central Ideas and Details",3,"Which statement best summarizes the text?",[["Confident social judgments can disclose the expectations of those making them rather than reliably establish another person's motives.","Уверенность сообщества показывает его интересы, а не гарантирует знание мотивов."],["The narrative's irony confirms that every local judgment is an objective report.","Ирония создаёт дистанцию от такой уверенности."],["Arrivals and invitations have no significance to any characters in the novel.","Они интерпретируются через важные социальные ожидания."],["A community can know a newcomer's intentions only if it has no shared expectations.","Такое необходимое условие не формулируется."]]],
["Inferences",3,"Which reading strategy best follows from this account?",[["Ask whose interests a confident statement serves before treating it as the narrator's unqualified judgment.","Это учитывает дистанцию между озвученным суждением и нейтральным фактом."],["Assume that every confident statement supplies direct access to every character's private intentions.","Уверенность сама по себе не гарантирует такого доступа."],["Ignore the social setting because irony removes all relation between speech and context.","Контекст необходим для понимания ожиданий."],["Read every invitation as proof of the same motive regardless of who interprets it.","Это воспроизводит некритичную единственную трактовку."]]],
["Text Structure and Purpose",2,"What does the final sentence accomplish?",[["It generalizes the interpretive consequence of the narrative distance described just before it.","Финал объясняет, что уверенная оценка говорит об оценивающих."],["It resolves every character's marital plans by listing their eventual outcomes.","Исходы отношений не перечислены."],["It denies that the community has any recognizable priorities.","Приоритеты сообщества составляют часть объяснения."],["It establishes that all apparent judgments in the novel are direct quotations from historians.","Исторических цитат и такого утверждения нет."]]],
]);
r("creature-judgment","shelley","Chapters 11–15: the creature observes the De Lacey household",
"Shelley's creature learns about human relationships while observing a family from a place where he remains unseen. He gradually connects words with actions and imagines that understanding the family's language might make recognition possible. Yet knowledge of their speech does not remove the effect of his appearance on an eventual encounter. The episode separates acquiring a means of communication from being granted a fair opportunity to use it: linguistic understanding alone cannot guarantee social acceptance.",[
["Central Ideas and Details",2,"Which choice best states the main idea?",[["Learning a community's language can enable understanding without ensuring that the community will accept the learner.","Языковой доступ и социальное признание не тождественны."],["The creature's observation prevents him from learning anything about human actions.","Он связывает слова и поступки."],["Speaking the same language guarantees that an encounter will be free from prejudice.","Такой гарантии текст прямо не даёт."],["The family's language has no connection to the creature's hopes for recognition.","Он связывает с языком надежду на признание."]]],
["Inferences",3,"Which inference is best supported?",[["A barrier to communication may persist on the listener's side even after the speaker has acquired the necessary language.","Реакция на внешность может закрывать доступ независимо от навыка говорящего."],["Every unsuccessful encounter proves that its participants lack a common language.","Эпизод разделяет общий язык и принятие."],["Observation can provide linguistic knowledge only if observers are immediately welcomed.","Он учится, оставаясь невидимым."],["Social acceptance always precedes any understanding of another person's actions.","Понимание действий здесь возникает до принятия."]]],
["Text Structure and Purpose",3,"How does the final sentence relate to the episode?",[["It articulates a broader distinction between possessing a communicative capacity and receiving a fair hearing.","Сюжет раскрывает различие способности говорить и возможности быть услышанным."],["It claims that learning the language was entirely unsuccessful.","Языковое обучение успешно, но недостаточно для принятия."],["It explains why the creature has no interest in relationships.","Интерес к семье и признанию прямо описан."],["It shifts the discussion from social relations to the mechanics of sound production.","Физиология звука не обсуждается."]]],
]);
r("unrecorded-kindness","eliot","Finale: Dorothea and unhistoric acts",
"Middlemarch's closing account of Dorothea directs attention away from fame as the sole measure of a life's effects. Actions that enter no celebrated public record can still influence the conditions in which other people live. The argument does not require a hidden achievement to be secretly equivalent to a famous one. It questions whether recognition and consequence should be treated as the same thing, allowing an ordinary, dispersed influence to matter without turning it into a conventional heroic spectacle.",[
["Central Ideas and Details",3,"Which statement best conveys the main idea?",[["A life's meaningful effects can exceed what public recognition or celebrated records reveal.","Последствия поступков не исчерпываются известностью."],["An unrecorded action has value only if it later receives the same fame as a heroic achievement.","Превращение в публичный подвиг не требуется."],["Every famous person's actions have fewer consequences than any private action.","Ранжирование всех известных и частных поступков не дано."],["Public records accurately capture every influence one person's life has on another.","Полнота публичной записи как раз оспаривается."]]],
["Inferences",3,"Which evidence would best support the distinction?",[["Private acts of assistance alter other people's opportunities even though the benefactor never becomes widely known.","Изменение возможностей показывает последствия без известности."],["A biography records a famous achievement without discussing any of its consequences.","Само отсутствие обсуждения не показывает непризнанное влияние."],["An individual becomes famous solely for repeating a claim about fame.","Это не пример полезных последствий без признания."],["A public celebration is attended by people who know nothing about its subject.","Такое незнание не раскрывает последствия частных действий."]]],
["Text Structure and Purpose",3,"What is the effect of saying the hidden achievement need not be equivalent to a famous one?",[["It avoids defending ordinary influence only by forcing it into the same scale used for public heroism.","Обыденное влияние признаётся без подгонки под героическую мерку."],["It withdraws the claim that uncelebrated actions can matter.","Ценность таких поступков сохраняется."],["It establishes that all consequences can be measured by the size of a spectacle.","Именно этот критерий подвергается сомнению."],["It denies that Dorothea's actions affect anyone beyond herself.","Воздействие на других — основная мысль."]]],
]);
r("bread-gift","douglass","Chapter VII: learning from boys in exchange for bread",
"Douglass recounts obtaining reading lessons from boys he encountered while carrying out errands. Exchanges involving bread helped create opportunities that formal instruction had denied him. The account shows resourcefulness under restriction rather than a simple absence of help: his learning depended on finding particular openings within an environment organized against it. The importance of his initiative is not diminished by acknowledging the small, uneven forms of cooperation through which that initiative could work.",[
["Central Ideas and Details",2,"Which statement best summarizes the passage?",[["Douglass's resourcefulness involved locating limited cooperation within circumstances that restricted his education.","Самостоятельная инициатива действует через конкретные возможности помощи."],["Douglass's initiative is disproved by the fact that other people sometimes helped him.","Инициатива и помощь не противопоставлены."],["Formal education was readily available, making informal exchanges unnecessary.","Формальное обучение было ограничено."],["The boys provided complete institutional protection against every restriction he faced.","Небольшие возможности не равны полной защите."]]],
["Inferences",3,"Which generalization is best supported?",[["A person's agency can operate through relationships without requiring that the surrounding system be supportive.","Локальное сотрудничество возможно внутри враждебной системы."],["An unsupportive system prevents every possible instance of cooperation between individuals.","Описанные уроки являются контрпримером."],["Accepting help always transfers all responsibility for learning to the helper.","Самостоятельность ученика сохраняется."],["Restrictions on education disappear as soon as one informal lesson occurs.","Частная возможность не отменяет систему ограничений."]]],
["Text Structure and Purpose",2,"Why does the text reject a 'simple absence of help' interpretation?",[["To describe initiative more accurately as the use of limited opportunities rather than absolute isolation.","Уточняется форма самостоятельности без мифа о полном одиночестве."],["To deny that restrictions played any role in the account.","Ограничения являются существенными условиями."],["To show that institutional permission had already been granted.","Формальный доступ оставался закрытым."],["To argue that the exchanges prevented rather than enabled learning.","Они открывали возможности уроков."]]],
]);

